```html
<!DOCTYPE html>
<html lang="en" data-theme="daylight">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Clara Moreau — Freelance Editorial & Architectural Photographer</title>
  <meta name="description" content="Portfolio of Clara Moreau, freelance editorial, architectural, and fine-art photographer based between Paris and Lisbon." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&family=Inter:wght@300;400;500&family=JetBrains+Mono:wght@300;400&display=swap" rel="stylesheet" />

  <style>
    :root {
      --bg: #F6F4EF;
      --bg-elevated: #ECE9E1;
      --bg-card: #EFECE5;
      --bg-nav: rgba(246, 244, 239, 0.86);
      --ink: #171715;
      --ink-muted: #64615A;
      --ink-faint: #949087;
      --border: rgba(23, 23, 21, 0.12);
      --border-strong: rgba(23, 23, 21, 0.28);
      --accent: #A25838;
      --accent-soft: rgba(162, 88, 56, 0.12);
      --mat-bg: #FCFBF8;
      --shadow-soft: 0 20px 50px rgba(23, 23, 21, 0.08);
      --shadow-hover: 0 28px 64px rgba(23, 23, 21, 0.14);

      --font-serif: 'Cormorant Garamond', Georgia, 'Times New Roman', serif;
      --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

      --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
      --container: 1380px;
      --nav-height: 76px;
    }

    [data-theme="darkroom"] {
      --bg: #10100F;
      --bg-elevated: #181816;
      --bg-card: #151513;
      --bg-nav: rgba(16, 16, 15, 0.86);
      --ink: #EAE6DF;
      --ink-muted: #9A958B;
      --ink-faint: #66625A;
      --border: rgba(234, 230, 223, 0.12);
      --border-strong: rgba(234, 230, 223, 0.3);
      --accent: #D9855C;
      --accent-soft: rgba(217, 133, 92, 0.14);
      --mat-bg: #191917;
      --shadow-soft: 0 24px 60px rgba(0, 0, 0, 0.45);
      --shadow-hover: 0 32px 72px rgba(0, 0, 0, 0.65);
    }

    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html {
      scroll-behavior: smooth;
      font-size: 16px;
      background-color: var(--bg);
      color: var(--ink);
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    body {
      font-family: var(--font-sans);
      background-color: var(--bg);
      color: var(--ink);
      line-height: 1.6;
      transition: background-color 0.45s var(--ease-out), color 0.45s var(--ease-out);
      overflow-x: hidden;
    }

    img {
      display: block;
      max-width: 100%;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button, input, textarea, select {
      font: inherit;
      color: inherit;
      background: none;
      border: none;
    }

    button {
      cursor: pointer;
    }

    ::selection {
      background: var(--accent);
      color: #fff;
    }

    /* Utility & Layout */
    .container {
      width: 100%;
      max-width: var(--container);
      margin: 0 auto;
      padding: 0 clamp(20px, 4vw, 56px);
    }

    .mono {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .serif {
      font-family: var(--font-serif);
    }

    .section {
      padding: clamp(72px, 10vw, 136px) 0;
      border-top: 1px solid var(--border);
    }

    .section-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: clamp(36px, 5vw, 64px);
      flex-wrap: wrap;
    }

    .section-kicker {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      color: var(--ink-muted);
      margin-bottom: 12px;
    }

    .section-kicker::before {
      content: '';
      width: 24px;
      height: 1px;
      background: var(--border-strong);
    }

    .section-title {
      font-family: var(--font-serif);
      font-weight: 400;
      font-size: clamp(2.1rem, 4.2vw, 3.6rem);
      line-height: 1.06;
      letter-spacing: -0.015em;
    }

    /* Header / Navigation */
    .site-header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      height: var(--nav-height);
      z-index: 90;
      display: flex;
      align-items: center;
      background: transparent;
      transition: background-color 0.35s var(--ease-out), border-color 0.35s var(--ease-out), backdrop-filter 0.35s var(--ease-out);
      border-bottom: 1px solid transparent;
    }

    .site-header.scrolled {
      background: var(--bg-nav);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom-color: var(--border);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }

    .brand {
      display: flex;
      align-items: baseline;
      gap: 14px;
    }

    .brand-name {
      font-family: var(--font-serif);
      font-size: 1.4rem;
      font-weight: 500;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .brand-status {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      color: var(--ink-muted);
      font-size: 0.72rem;
    }

    .status-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: #4E9A6F;
      box-shadow: 0 0 0 3px rgba(78, 154, 111, 0.2);
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-link {
      font-size: 0.84rem;
      color: var(--ink-muted);
      position: relative;
      padding: 4px 0;
      transition: color 0.25s ease;
    }

    .nav-link::after {
      content: '';
      position: absolute;
      left: 0;
      bottom: 0;
      width: 100%;
      height: 1px;
      background: var(--ink);
      transform: scaleX(0);
      transform-origin: right;
      transition: transform 0.35s var(--ease-out);
    }

    .nav-link:hover,
    .nav-link.active {
      color: var(--ink);
    }

    .nav-link:hover::after,
    .nav-link.active::after {
      transform: scaleX(1);
      transform-origin: left;
    }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 14px;
    }

    .theme-toggle {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 7px 13px;
      border-radius: 999px;
      border: 1px solid var(--border-strong);
      font-family: var(--font-mono);
      font-size: 0.68rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--ink);
      transition: background-color 0.25s ease, border-color 0.25s ease;
    }

    .theme-toggle:hover {
      background: var(--bg-elevated);
    }

    .theme-indicator {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--accent);
      transition: transform 0.35s var(--ease-out);
    }

    .mobile-menu-btn {
      display: none;
      width: 38px;
      height: 38px;
      align-items: center;
      justify-content: center;
      border: 1px solid var(--border);
      border-radius: 50%;
    }

    .mobile-drawer {
      display: none;
      position: fixed;
      inset: var(--nav-height) 0 0 0;
      background: var(--bg);
      z-index: 85;
      padding: 36px 24px;
      flex-direction: column;
      justify-content: space-between;
      border-top: 1px solid var(--border);
    }

    .mobile-drawer.open {
      display: flex;
    }

    .mobile-drawer-links {
      display: flex;
      flex-direction: column;
      gap: 20px;
    }

    .mobile-drawer-links a {
      font-family: var(--font-serif);
      font-size: 2.2rem;
      font-weight: 400;
      border-bottom: 1px solid var(--border);
      padding-bottom: 14px;
    }

    /* Hero Section */
    .hero {
      padding-top: calc(var(--nav-height) + clamp(32px, 5vw, 72px));
      padding-bottom: clamp(64px, 8vw, 110px);
      min-height: 92vh;
      display: flex;
      align-items: center;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
      gap: clamp(36px, 6vw, 88px);
      align-items: center;
    }

    .hero-meta {
      display: flex;
      align-items: center;
      gap: 16px;
      color: var(--ink-muted);
      margin-bottom: 24px;
      flex-wrap: wrap;
    }

    .hero-meta-sep {
      width: 4px;
      height: 4px;
      border-radius: 50%;
      background: var(--border-strong);
    }

    .hero-title {
      font-family: var(--font-serif);
      font-weight: 300;
      font-size: clamp(2.8rem, 6vw, 5.2rem);
      line-height: 1.01;
      letter-spacing: -0.02em;
      margin-bottom: 28px;
    }

    .hero-title em {
      font-style: italic;
      color: var(--accent);
      font-weight: 300;
    }

    .hero-desc {
      max-width: 46ch;
      color: var(--ink-muted);
      font-size: clamp(0.96rem, 1.15vw, 1.06rem);
      font-weight: 300;
      margin-bottom: 38px;
      line-height: 1.72;
    }

    .hero-actions {
      display: flex;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
      margin-bottom: 48px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      padding: 13px 26px;
      border-radius: 999px;
      font-size: 0.85rem;
      font-weight: 400;
      letter-spacing: 0.02em;
      transition: transform 0.25s var(--ease-out), background-color 0.25s ease, color 0.25s ease, border-color 0.25s ease;
    }

    .btn:active {
      transform: scale(0.98);
    }

    .btn-primary {
      background: var(--ink);
      color: var(--bg);
      border: 1px solid var(--ink);
    }

    .btn-primary:hover {
      background: var(--accent);
      border-color: var(--accent);
      color: #fff;
    }

    .btn-outline {
      border: 1px solid var(--border-strong);
      color: var(--ink);
    }

    .btn-outline:hover {
      background: var(--bg-elevated);
      border-color: var(--ink);
    }

    .hero-stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 20px;
      padding-top: 28px;
      border-top: 1px solid var(--border);
      max-width: 460px;
    }

    .stat-num {
      font-family: var(--font-serif);
      font-size: 1.85rem;
      line-height: 1.1;
      margin-bottom: 4px;
    }

    .stat-label {
      font-size: 0.74rem;
      color: var(--ink-muted);
    }

    /* Hero Exhibition Print Frame */
    .hero-showcase {
      position: relative;
    }

    .print-mat {
      background: var(--mat-bg);
      padding: clamp(16px, 2.2vw, 28px);
      border: 1px solid var(--border);
      box-shadow: var(--shadow-soft);
      transition: background-color 0.45s var(--ease-out), box-shadow 0.45s var(--ease-out);
    }

    .hero-frame {
      position: relative;
      aspect-ratio: 4 / 5;
      overflow: hidden;
      background: var(--bg-elevated);
      cursor: zoom-in;
    }

    .hero-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: opacity 0.55s var(--ease-out), transform 0.9s var(--ease-out);
    }

    .hero-frame:hover img {
      transform: scale(1.025);
    }

    .hero-frame.switching img {
      opacity: 0.15;
    }

    .hero-plate-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding-top: 16px;
      margin-top: 14px;
      border-top: 1px solid var(--border);
    }

    .hero-plate-info h3 {
      font-family: var(--font-serif);
      font-weight: 400;
      font-size: 1.2rem;
      line-height: 1.2;
    }

    .hero-plate-info p {
      color: var(--ink-muted);
      margin-top: 2px;
    }

    .hero-plate-controls {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-shrink: 0;
    }

    .icon-btn {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      border: 1px solid var(--border-strong);
      display: inline-flex;
      align-items: center;
      justify-content: center;
      color: var(--ink);
      transition: background-color 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
    }

    .icon-btn:hover {
      background: var(--ink);
      color: var(--bg);
      border-color: var(--ink);
    }

    /* Gallery Controls */
    .gallery-toolbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      flex-wrap: wrap;
      padding-bottom: 24px;
      margin-bottom: 36px;
      border-bottom: 1px solid var(--border);
    }

    .filter-pills {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
    }

    .filter-btn {
      padding: 8px 16px;
      border-radius: 999px;
      font-size: 0.82rem;
      color: var(--ink-muted);
      border: 1px solid transparent;
      transition: all 0.25s ease;
    }

    .filter-btn:hover {
      color: var(--ink);
      border-color: var(--border);
    }

    .filter-btn.active {
      background: var(--ink);
      color: var(--bg);
      border-color: var(--ink);
    }

    .filter-count {
      font-family: var(--font-mono);
      font-size: 0.68rem;
      opacity: 0.65;
      margin-left: 4px;
    }

    .view-switcher {
      display: inline-flex;
      padding: 4px;
      border-radius: 999px;
      border: 1px solid var(--border);
      background: var(--bg-elevated);
    }

    .view-btn {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      padding: 6px 14px;
      border-radius: 999px;
      font-family: var(--font-mono);
      font-size: 0.68rem;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      color: var(--ink-muted);
      transition: all 0.25s ease;
    }

    .view-btn.active {
      background: var(--bg);
      color: var(--ink);
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    }

    /* Editorial Gallery Grid */
    .gallery-editorial {
      display: grid;
      grid-template-columns: repeat(12, minmax(0, 1fr));
      gap: clamp(24px, 3.2vw, 48px) clamp(18px, 2.5vw, 34px);
      align-items: start;
    }

    .photo-card {
      grid-column: span 6;
      cursor: pointer;
      group: true;
      opacity: 0;
      transform: translateY(18px);
      animation: fadeUp 0.65s var(--ease-out) forwards;
    }

    /* Editorial asymmetric rhythm */
    .photo-card.span-7 { grid-column: span 7; }
    .photo-card.span-5 { grid-column: span 5; }
    .photo-card.span-4 { grid-column: span 4; }
    .photo-card.span-8 { grid-column: span 8; }
    .photo-card.offset-top { margin-top: clamp(0px, 4vw, 52px); }

    @keyframes fadeUp {
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    .photo-frame {
      position: relative;
      overflow: hidden;
      background: var(--bg-elevated);
      border: 1px solid var(--border);
    }

    .photo-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.8s var(--ease-out), filter 0.45s ease;
    }

    .photo-card:hover .photo-frame img {
      transform: scale(1.035);
    }

    .photo-hover-badge {
      position: absolute;
      bottom: 14px;
      right: 14px;
      padding: 6px 12px;
      border-radius: 999px;
      background: rgba(16, 16, 15, 0.72);
      color: #F4F1EA;
      backdrop-filter: blur(8px);
      opacity: 0;
      transform: translateY(6px);
      transition: opacity 0.3s ease, transform 0.3s var(--ease-out);
      pointer-events: none;
    }

    .photo-card:hover .photo-hover-badge {
      opacity: 1;
      transform: translateY(0);
    }

    .photo-meta {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 16px;
      padding-top: 14px;
    }

    .photo-title {
      font-family: var(--font-serif);
      font-size: 1.32rem;
      font-weight: 400;
      line-height: 1.2;
      transition: color 0.25s ease;
    }

    .photo-card:hover .photo-title {
      color: var(--accent);
    }

    .photo-sub {
      color: var(--ink-muted);
      font-size: 0.82rem;
      margin-top: 2px;
    }

    .photo-index {
      color: var(--ink-faint);
      flex-shrink: 0;
    }

    /* Analog Contact Sheet Mode */
    .gallery-contact-sheet {
      background: #121211;
      color: #D8D4CB;
      padding: clamp(20px, 3vw, 38px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      box-shadow: var(--shadow-soft);
    }

    .contact-sheet-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 12px;
      padding-bottom: 20px;
      margin-bottom: 24px;
      border-bottom: 1px dashed rgba(255, 255, 255, 0.16);
      font-family: var(--font-mono);
      font-size: 0.7rem;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: #A59E92;
    }

    .contact-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 24px 16px;
    }

    .contact-frame {
      position: relative;
      cursor: pointer;
      padding: 20px 8px 22px;
      background: #0A0A09;
      border-top: 1px solid rgba(255, 255, 255, 0.08);
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      transition: transform 0.25s var(--ease-out), background-color 0.25s ease;
    }

    .contact-frame:hover {
      background: #171715;
      transform: translateY(-2px);
    }

    /* Film sprockets */
    .sprockets {
      display: flex;
      justify-content: space-between;
      padding: 0 6px;
      position: absolute;
      left: 0;
      right: 0;
    }

    .sprockets.top { top: 5px; }
    .sprockets.bottom { bottom: 5px; }

    .sprockets span {
      width: 11px;
      height: 7px;
      border-radius: 1.5px;
      background: #1C1C1A;
      border: 1px solid rgba(255, 255, 255, 0.06);
    }

    .contact-rebate {
      display: flex;
      justify-content: space-between;
      font-family: var(--font-mono);
      font-size: 0.6rem;
      letter-spacing: 0.08em;
      color: #C79658;
      margin-bottom: 6px;
      padding: 0 2px;
      opacity: 0.85;
    }

    .contact-img-wrap {
      position: relative;
      aspect-ratio: 4 / 3;
      overflow: hidden;
      background: #1B1B19;
    }

    .contact-img-wrap img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.45s var(--ease-out);
    }

    .contact-frame:hover .contact-img-wrap img {
      transform: scale(1.04);
    }

    /* Grease pencil editor select mark */
    .grease-mark {
      position: absolute;
      inset: 6px;
      border: 2px solid rgba(224, 92, 62, 0.82);
      border-radius: 48% 52% 46% 54% / 52% 44% 56% 48%;
      transform: rotate(-1.5deg);
      pointer-events: none;
      box-shadow: 0 0 8px rgba(224, 92, 62, 0.25);
    }

    .contact-caption {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-top: 7px;
      font-family: var(--font-mono);
      font-size: 0.62rem;
      color: #9C968B;
      padding: 0 2px;
    }

    /* About & Practice Section */
    .about-grid {
      display: grid;
      grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
      gap: clamp(36px, 6vw, 88px);
      align-items: start;
    }

    .portrait-card {
      position: sticky;
      top: calc(var(--nav-height) + 28px);
    }

    .portrait-frame {
      aspect-ratio: 4 / 5;
      overflow: hidden;
      border: 1px solid var(--border);
      background: var(--bg-elevated);
      margin-bottom: 14px;
    }

    .portrait-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .about-lead {
      font-family: var(--font-serif);
      font-size: clamp(1.65rem, 2.8vw, 2.35rem);
      font-weight: 400;
      line-height: 1.25;
      margin-bottom: 24px;
    }

    .about-body {
      color: var(--ink-muted);
      font-weight: 300;
      font-size: 1rem;
      line-height: 1.8;
      display: flex;
      flex-direction: column;
      gap: 18px;
      margin-bottom: 42px;
      max-width: 60ch;
    }

    .services-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 24px;
      padding: 32px 0;
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
      margin-bottom: 42px;
    }

    .service-item h4 {
      font-family: var(--font-serif);
      font-size: 1.28rem;
      font-weight: 500;
      margin-bottom: 6px;
    }

    .service-item p {
      font-size: 0.86rem;
      color: var(--ink-muted);
      line-height: 1.65;
    }

    .clients-list {
      display: flex;
      flex-wrap: wrap;
      gap: 10px 26px;
      margin-top: 16px;
      margin-bottom: 46px;
    }

    .clients-list span {
      font-family: var(--font-serif);
      font-size: 1.35rem;
      color: var(--ink-muted);
      transition: color 0.2s ease;
    }

    .clients-list span:hover {
      color: var(--ink);
    }

    .cv-table {
      width: 100%;
      border-collapse: collapse;
      margin-top: 14px;
    }

    .cv-table tr {
      border-bottom: 1px solid var(--border);
    }

    .cv-table td {
      padding: 14px 0;
      font-size: 0.88rem;
      vertical-align: top;
    }

    .cv-table td:first-child {
      width: 78px;
      font-family: var(--font-mono);
      font-size: 0.74rem;
      color: var(--ink-faint);
    }

    .cv-table td:last-child {
      text-align: right;
      color: var(--ink-muted);
      font-size: 0.82rem;
    }

    /* Inquiry Section */
    .inquiry-grid {
      display: grid;
      grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
      gap: clamp(36px, 6vw, 88px);
      align-items: start;
    }

    .inquiry-info p {
      color: var(--ink-muted);
      max-width: 44ch;
      margin-bottom: 32px;
      font-weight: 300;
      line-height: 1.75;
    }

    .direct-contact {
      display: flex;
      flex-direction: column;
      gap: 18px;
      padding: 24px 0;
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
      margin-bottom: 28px;
    }

    .contact-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      flex-wrap: wrap;
    }

    .contact-email {
      font-family: var(--font-serif);
      font-size: 1.55rem;
      border-bottom: 1px solid var(--border-strong);
      padding-bottom: 2px;
      transition: color 0.2s ease, border-color 0.2s ease;
    }

    .contact-email:hover {
      color: var(--accent);
      border-color: var(--accent);
    }

    .copy-btn {
      padding: 6px 12px;
      border-radius: 999px;
      border: 1px solid var(--border-strong);
      font-family: var(--font-mono);
      font-size: 0.66rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--ink-muted);
      transition: all 0.2s ease;
    }

    .copy-btn:hover {
      color: var(--ink);
      background: var(--bg-elevated);
    }

    .studio-addresses {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 20px;
      font-size: 0.85rem;
      color: var(--ink-muted);
    }

    .studio-addresses strong {
      display: block;
      color: var(--ink);
      font-weight: 500;
      margin-bottom: 4px;
    }

    /* Form */
    .inquiry-form-wrap {
      background: var(--mat-bg);
      border: 1px solid var(--border);
      padding: clamp(24px, 3.5vw, 44px);
    }

    .selected-print-banner {
      display: none;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 12px 14px;
      margin-bottom: 24px;
      background: var(--accent-soft);
      border: 1px solid var(--accent);
      font-size: 0.84rem;
    }

    .selected-print-banner.visible {
      display: flex;
    }

    .inquiry-types {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-bottom: 26px;
    }

    .type-chip {
      padding: 8px 14px;
      border-radius: 999px;
      border: 1px solid var(--border-strong);
      font-size: 0.8rem;
      color: var(--ink-muted);
      transition: all 0.2s ease;
    }

    .type-chip.active {
      background: var(--ink);
      color: var(--bg);
      border-color: var(--ink);
    }

    .form-row {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 18px;
    }

    .field {
      display: flex;
      flex-direction: column;
      gap: 8px;
      margin-bottom: 20px;
    }

    .field label {
      font-family: var(--font-mono);
      font-size: 0.68rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--ink-muted);
    }

    .field input,
    .field textarea,
    .field select {
      width: 100%;
      padding: 12px 14px;
      border: 1px solid var(--border-strong);
      background: var(--bg);
      font-size: 0.92rem;
      transition: border-color 0.25s ease, box-shadow 0.25s ease;
    }

    .field input:focus,
    .field textarea:focus,
    .field select:focus {
      outline: none;
      border-color: var(--accent);
    }

    .field textarea {
      min-height: 126px;
      resize: vertical;
    }

    .form-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      flex-wrap: wrap;
      margin-top: 8px;
    }

    .form-note {
      font-size: 0.78rem;
      color: var(--ink-faint);
    }

    .form-success {
      display: none;
      text-align: center;
      padding: 36px 16px;
    }

    .form-success.visible {
      display: block;
    }

    .form-success h3 {
      font-family: var(--font-serif);
      font-size: 2rem;
      font-weight: 400;
      margin-bottom: 10px;
    }

    .form-success p {
      color: var(--ink-muted);
      margin-bottom: 24px;
      max-width: 42ch;
      margin-inline: auto;
    }

    /* Footer */
    .site-footer {
      border-top: 1px solid var(--border);
      padding: 34px 0;
    }

    .footer-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 20px;
      font-size: 0.82rem;
      color: var(--ink-muted);
    }

    .footer-links {
      display: flex;
      align-items: center;
      gap: 24px;
    }

    .footer-links a:hover {
      color: var(--ink);
    }

    /* Lightbox Modal */
    .lightbox {
      position: fixed;
      inset: 0;
      z-index: 200;
      background: rgba(12, 12, 11, 0.96);
      color: #EAE6DF;
      display: flex;
      flex-direction: column;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.35s var(--ease-out);
      backdrop-filter: blur(12px);
    }

    .lightbox.open {
      opacity: 1;
      pointer-events: auto;
    }

    .lb-topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 18px clamp(18px, 3vw, 36px);
      border-bottom: 1px solid rgba(234, 230, 223, 0.12);
      flex-shrink: 0;
    }

    .lb-top-actions {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .lb-btn {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      padding: 7px 14px;
      border-radius: 999px;
      border: 1px solid rgba(234, 230, 223, 0.22);
      color: #EAE6DF;
      font-family: var(--font-mono);
      font-size: 0.68rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      transition: all 0.2s ease;
    }

    .lb-btn:hover,
    .lb-btn.active {
      background: #EAE6DF;
      color: #10100F;
      border-color: #EAE6DF;
    }

    .lb-stage-wrap {
      flex: 1;
      min-height: 0;
      display: flex;
      position: relative;
      overflow: hidden;
    }

    .lb-stage {
      flex: 1;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: clamp(16px, 3vw, 44px);
      overflow: hidden;
    }

    .lb-img-container {
      position: relative;
      max-width: 100%;
      max-height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: zoom-in;
      overflow: hidden;
    }

    .lb-img-container.zoomed {
      cursor: zoom-out;
    }

    .lb-img-container img {
      max-width: 100%;
      max-height: calc(100vh - 165px);
      width: auto;
      height: auto;
      object-fit: contain;
      box-shadow: 0 28px 80px rgba(0, 0, 0, 0.65);
      transition: transform 0.35s var(--ease-out);
      transform-origin: center center;
    }

    .lb-nav {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 46px;
      height: 46px;
      border-radius: 50%;
      background: rgba(20, 20, 18, 0.72);
      border: 1px solid rgba(234, 230, 223, 0.22);
      color: #EAE6DF;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      z-index: 5;
      transition: all 0.2s ease;
    }

    .lb-nav:hover {
      background: #EAE6DF;
      color: #10100F;
    }

    .lb-nav.prev { left: 20px; }
    .lb-nav.next { right: 20px; }

    /* Lightbox Technical / EXIF Drawer */
    .lb-drawer {
      width: 340px;
      flex-shrink: 0;
      border-left: 1px solid rgba(234, 230, 223, 0.12);
      background: #141412;
      padding: 28px 26px;
      overflow-y: auto;
      display: flex;
      flex-direction: column;
      gap: 22px;
      transition: margin-right 0.35s var(--ease-out), opacity 0.3s ease;
    }

    .lb-drawer.collapsed {
      margin-right: -340px;
      opacity: 0;
      pointer-events: none;
    }

    .lb-title {
      font-family: var(--font-serif);
      font-size: 1.85rem;
      font-weight: 400;
      line-height: 1.15;
    }

    .lb-location {
      color: #A09A8E;
      font-size: 0.86rem;
      margin-top: 4px;
    }

    .lb-note {
      color: #C9C4BA;
      font-size: 0.88rem;
      line-height: 1.7;
      font-weight: 300;
    }

    .exif-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px 12px;
      padding: 18px 0;
      border-top: 1px solid rgba(234, 230, 223, 0.12);
      border-bottom: 1px solid rgba(234, 230, 223, 0.12);
    }

    .exif-cell span {
      display: block;
      font-family: var(--font-mono);
      font-size: 0.62rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: #827D73;
      margin-bottom: 3px;
    }

    .exif-cell strong {
      font-size: 0.82rem;
      font-weight: 400;
      color: #EAE6DF;
    }

    .histogram-box {
      background: #0D0D0C;
      border: 1px solid rgba(234, 230, 223, 0.1);
      padding: 12px;
    }

    .histogram-head {
      display: flex;
      justify-content: space-between;
      font-family: var(--font-mono);
      font-size: 0.6rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: #827D73;
      margin-bottom: 8px;
    }

    #lbHistogram {
      width: 100%;
      height: 54px;
      display: block;
    }

    .edition-box {
      padding: 14px;
      border: 1px solid rgba(234, 230, 223, 0.14);
      background: rgba(255, 255, 255, 0.02);
      font-size: 0.8rem;
      color: #B4AEA3;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .lb-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 12px clamp(18px, 3vw, 36px);
      border-top: 1px solid rgba(234, 230, 223, 0.12);
      font-family: var(--font-mono);
      font-size: 0.66rem;
      letter-spacing: 0.08em;
      color: #8E897E;
      flex-shrink: 0;
    }

    /* Toast Notification */
    .toast {
      position: fixed;
      bottom: 24px;
      left: 50%;
      transform: translateX(-50%) translateY(20px);
      background: var(--ink);
      color: var(--bg);
      padding: 11px 20px;
      border-radius: 999px;
      font-size: 0.82rem;
      z-index: 300;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.25s ease, transform 0.3s var(--ease-out);
      box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
    }

    .toast.visible {
      opacity: 1;
      transform: translateX(-50%) translateY(0);
    }

    /* Responsive Breakpoints */
    @media (max-width: 1080px) {
      .hero-grid,
      .about-grid,
      .inquiry-grid {
        grid-template-columns: 1fr;
      }

      .portrait-card {
        position: static;
        max-width: 420px;
      }

      .contact-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .lb-drawer {
        position: absolute;
        top: 0;
        right: 0;
        bottom: 0;
        z-index: 10;
        max-width: 88vw;
      }
    }

    @media (max-width: 820px) {
      .nav-links,
      .brand-status {
        display: none;
      }

      .mobile-menu-btn {
        display: inline-flex;
      }

      .photo-card,
      .photo-card.span-7,
      .photo-card.span-5,
      .photo-card.span-4,
      .photo-card.span-8 {
        grid-column: span 12;
        margin-top: 0;
      }

      .contact-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .services-grid,
      .form-row,
      .studio-addresses {
        grid-template-columns: 1fr;
      }

      .lb-nav {
        width: 38px;
        height: 38px;
      }

      .lb-nav.prev { left: 10px; }
      .lb-nav.next { right: 10px; }

      .lb-footer .lb-shortcuts {
        display: none;
      }
    }

    @media (max-width: 520px) {
      .contact-grid {
        grid-template-columns: 1fr;
      }

      .hero-stats {
        grid-template-columns: repeat(3, 1fr);
        gap: 12px;
      }
    }
  </style>
</head>
<body>

  <!-- Header -->
  <header class="site-header" id="siteHeader">
