            <line x1="4" y1="16" x2="20" y2="16"></line>
          </svg>
        </button>
      </div>
    </div>
  </header>

  <!-- Mobile Navigation Drawer -->
  <div class="mobile-drawer" id="mobileDrawer" aria-hidden="true">
    <div class="mobile-drawer-links">
      <a href="#work" class="mobile-nav-link">Selected Work</a>
      <a href="#about" class="mobile-nav-link">Practice &amp; CV</a>
      <a href="#inquire" class="mobile-nav-link">Commissions &amp; Prints</a>
    </div>
    <div class="mono" style="color: var(--ink-muted);">
      Paris · Lisbon — studio@claramoreau.photo
    </div>
  </div>

  <!-- Main -->
  <main id="top">

    <!-- Hero -->
    <section class="hero">
      <div class="container hero-grid">
        <div class="hero-copy">
          <div class="hero-meta mono">
            <span>Editorial &amp; Architectural Photography</span>
            <span class="hero-meta-sep"></span>
            <span>Medium Format &amp; 35mm</span>
          </div>

          <h1 class="hero-title">
            Light, architecture, and the <em>quiet intervals</em> between.
          </h1>

          <p class="hero-desc">
            I am Clara Moreau, a freelance photographer working between Paris and Lisbon. Through analog film and patient observation, I craft atmospheric stories for magazines, architects, hospitality spaces, and cultural institutions.
          </p>

          <div class="hero-actions">
            <a href="#work" class="btn btn-primary">
              <span>Explore Selected Work</span>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8">
                <path d="M12 5v14M5 12l7 7 7-7"/>
              </svg>
            </a>
            <a href="#inquire" class="btn btn-outline">Commission Inquiry</a>
          </div>

