              <div class="stat-label">Published Stories</div>
            </div>
            <div>
              <div class="stat-num">12</div>
              <div class="stat-label">Archive Plates</div>
            </div>
          </div>
        </div>

        <div class="hero-showcase">
          <div class="print-mat">
            <div class="hero-frame" id="heroFrame" role="button" tabindex="0" aria-label="Inspect featured photograph in lightbox">
              <img id="heroImg" alt="Featured photograph" />
            </div>
            <div class="hero-plate-bar">
              <div class="hero-plate-info">
                <h3 id="heroPlateTitle">Pavilhão do Sol</h3>
                <p class="mono" id="heroPlateMeta">PLATE 01 / 12 · LISBON · PORTRA 400</p>
              </div>
              <div class="hero-plate-controls">
                <button class="icon-btn" id="heroPrev" aria-label="Previous featured plate">
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7">
                    <path d="M15 18l-6-6 6-6"/>
                  </svg>
                </button>
                <button class="icon-btn" id="heroNext" aria-label="Next featured plate">
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7">
