            <button class="filter-btn" data-category="Nocturnes">Nocturnes <span class="filter-count">3</span></button>
            <button class="filter-btn" data-category="Stillness">Stillness <span class="filter-count">3</span></button>
          </div>

          <div class="view-switcher" role="group" aria-label="Gallery display mode">
