                <rect x="3" y="3" width="8" height="10"/><rect x="13" y="3" width="8" height="7"/><rect x="13" y="12" width="8" height="9"/><rect x="3" y="15" width="8" height="6"/>
              </svg>
              <span>Editorial</span>
