    /* --------------------------------------------------------------------------
       PROCEDURAL DARKROOM HELPERS (GRAIN, VIGNETTE, HISTOGRAM, SEEDED RNG)
       -------------------------------------------------------------------------- */
    function mulberry32(seed) {
      return function() {
        let t = (seed += 0x6D2B79F5);
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
      };
    }

    let grainPatternCanvas = null;
    function getGrainCanvas() {
      if (grainPatternCanvas) return grainPatternCanvas;
      const c = document.createElement('canvas');
      c.width = 240;
      c.height = 240;
      const g = c.getContext('2d');
      const img = g.createImageData(240, 240);
      const rand = mulberry32(90210);
      for (let i = 0; i < img.data.length; i += 4) {
        // Approximate Gaussian noise for organic silver halide look
        const n = ((rand() + rand() + rand()) / 3) * 255;
        img.data[i] = n;
        img.data[i + 1] = n;
        img.data[i + 2] = n;
        img.data[i + 3] = 255;
      }
      g.putImageData(img, 0, 0);
      grainPatternCanvas = c;
      return c;
    }

    function applyFilmFinish(ctx, w, h, { grain = 0.095, vignette = 0.34, bw = false, warmTint = null } = {}) {
      if (warmTint) {
        ctx.save();
        ctx.globalCompositeOperation = 'soft-light';
        ctx.fillStyle = warmTint;
        ctx.fillRect(0, 0, w, h);
        ctx.restore();
      }

      if (bw) {
        const imgData = ctx.getImageData(0, 0, w, h);
        const d = imgData.data;
        for (let i = 0; i < d.length; i += 4) {
          // Subtle silver-gelatin tonal response
          let lum = 0.28 * d[i] + 0.61 * d[i + 1] + 0.11 * d[i + 2];
          // Gentle S-curve contrast
          let norm = lum / 255;
          norm = norm < 0.5
            ? 0.5 * Math.pow(2 * norm, 1.12)
            : 1 - 0.5 * Math.pow(2 * (1 - norm), 1.12);
          const v = Math.max(0, Math.min(255, norm * 255));
          // Slight warm fiber paper tone
          d[i] = Math.min(255, v * 1.015);
          d[i + 1] = v;
          d[i + 2] = v * 0.965;
        }
        ctx.putImageData(imgData, 0, 0);
      }

      // Optical lens vignette
      if (vignette > 0) {
        const vg = ctx.createRadialGradient(w * 0.5, h * 0.48, Math.min(w, h) * 0.28, w * 0.5, h * 0.5, Math.hypot(w, h) * 0.62);
        vg.addColorStop(0, 'rgba(0,0,0,0)');
        vg.addColorStop(0.7, `rgba(10,9,8,${(vignette * 0.35).toFixed(3)})`);
        vg.addColorStop(1, `rgba(8,7,6,${vignette.toFixed(3)})`);
        ctx.fillStyle = vg;
        ctx.fillRect(0, 0, w, h);
      }

      // Organic analog film grain
      if (grain > 0) {
        ctx.save();
        ctx.globalCompositeOperation = 'overlay';
        ctx.globalAlpha = grain;
        const pat = ctx.createPattern(getGrainCanvas(), 'repeat');
        ctx.fillStyle = pat;
        ctx.fillRect(0, 0, w, h);
        ctx.restore();
      }
    }

    function computeHistogram(ctx, w, h) {
      const bins = new Array(64).fill(0);
      const data = ctx.getImageData(0, 0, w, h).data;
      const step = 16; // sample every 4th pixel for instant speed
      for (let i = 0; i < data.length; i += step) {
        const lum = 0.299 * data[i] + 0.587 * data[i + 1] + 0.114 * data[i + 2];
        const idx = Math.min(63, Math.floor((lum / 256) * 64));
        bins[idx]++;
      }
      const max = Math.max(...bins, 1);
      return bins.map(v => v / max);
    }

    /* --------------------------------------------------------------------------
       12 BESPOKE PROCEDURAL FINE-ART PHOTOGRAPHIC PLATES
       -------------------------------------------------------------------------- */

    // 01: Pavilhão do Sol — Sunlit Lisbon brutalist courtyard, ochre wall, sharp shadow & deep blue sky
    function renderPavilhaoDoSol(ctx, w, h) {
      // Mediterranean cerulean sky
      const sky = ctx.createLinearGradient(0, 0, w * 0.3, h * 0.42);
      sky.addColorStop(0, '#2C5C88');
      sky.addColorStop(0.55, '#5484AC');
      sky.addColorStop(1, '#98B6CE');
      ctx.fillStyle = sky;
      ctx.fillRect(0, 0, w, h * 0.44);

      // Sunlit warm ochre-plaster architectural facade
      const wall = ctx.createLinearGradient(0, h * 0.2, w, h);
      wall.addColorStop(0, '#E9C598');
      wall.addColorStop(0.5, '#D8A978');
      wall.addColorStop(1, '#BE8A5A');
      ctx.fillStyle = wall;
      ctx.beginPath();
      ctx.moveTo(0, h * 0.24);
      ctx.lineTo(w * 0.72, h * 0.12);
      ctx.lineTo(w * 0.72, h);
      ctx.lineTo(0, h);
      ctx.closePath();
      ctx.fill();

      // Side concrete return wall in cool shadow
      const side = ctx.createLinearGradient(w * 0.72, h * 0.12, w, h);
      side.addColorStop(0, '#77685C');
      side.addColorStop(1, '#453C36');
      ctx.fillStyle = side;
      ctx.beginPath();
      ctx.moveTo(w * 0.72, h * 0.12);
      ctx.lineTo(w, h * 0.19);
      ctx.lineTo(w, h);
      ctx.lineTo(w * 0.72, h);
      ctx.closePath();
      ctx.fill();

      // Recessed minimalist arch portal
      const archX = w * 0.24, archW = w * 0.26, archTop = h * 0.48;
      ctx.fillStyle = '#332B27';
      ctx.beginPath();
      ctx.moveTo(archX, h);
      ctx.lineTo(archX, archTop + archW * 0.5);
      ctx.arc(archX + archW * 0.5, archTop + archW * 0.5, archW * 0.5, Math.PI, 0, false);
      ctx.lineTo(archX + archW, h);
      ctx.closePath();
      ctx.fill();

      // Illuminated inner reveal of the arch
      ctx.fillStyle = '#B88459';
      ctx.beginPath();
      ctx.moveTo(archX + archW * 0.82, h);
      ctx.lineTo(archX + archW * 0.82, archTop + archW * 0.5);
      ctx.arc(archX + archW * 0.5, archTop + archW * 0.5, archW * 0.34, 0, -Math.PI * 0.35, true);
      ctx.lineTo(archX + archW, archTop + archW * 0.5);
      ctx.lineTo(archX + archW, h);
      ctx.closePath();
      ctx.fill();

      // Sunlit stone courtyard floor
      const floor = ctx.createLinearGradient(0, h * 0.82, w, h);
      floor.addColorStop(0, '#D7C3A8');
      floor.addColorStop(1, '#9E8B74');
      ctx.fillStyle = floor;
      ctx.fillRect(0, h * 0.84, w, h * 0.16);

      // Razor-sharp diagonal afternoon shadow cutting across facade
      ctx.save();
      ctx.fillStyle = 'rgba(26, 23, 28, 0.56)';
      ctx.beginPath();
      ctx.moveTo(0, h * 0.38);
      ctx.lineTo(w * 0.58, h * 0.84);
      ctx.lineTo(w * 0.82, h);
      ctx.lineTo(0, h);
      ctx.closePath();
      ctx.fill();

      // Subtle architectural concrete tie-holes
      ctx.fillStyle = 'rgba(42, 30, 22, 0.22)';
      for (let row = 0; row < 4; row++) {
        for (let col = 0; col < 3; col++) {
          ctx.beginPath();
          ctx.arc(w * (0.1 + col * 0.24), h * (0.28 + row * 0.14), 2.5, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      ctx.restore();

      // Warm raking light bloom from upper right
      const sunGlow = ctx.createRadialGradient(w * 0.88, h * 0.08, 10, w * 0.72, h * 0.2, w * 0.8);
      sunGlow.addColorStop(0, 'rgba(255, 238, 200, 0.28)');
      sunGlow.addColorStop(1, 'rgba(255, 220, 160, 0)');
      ctx.fillStyle = sunGlow;
      ctx.fillRect(0, 0, w, h);

      applyFilmFinish(ctx, w, h, { grain: 0.09, vignette: 0.28, warmTint: 'rgba(255, 218, 180, 0.08)' });
    }

    // 02: Atlantic Fog III — Sugimoto-inspired minimalist misty seascape
    function renderAtlanticFog(ctx, w, h) {
      const horizon = h * 0.515;

      // Soft misty sky
      const sky = ctx.createLinearGradient(0, 0, 0, horizon);
      sky.addColorStop(0, '#A5A8AA');
      sky.addColorStop(0.55, '#C8CBCC');
      sky.addColorStop(1, '#E2E3E1');
      ctx.fillStyle = sky;
      ctx.fillRect(0, 0, w, horizon + 2);

      // Subtle diffused mist banks in sky
      ctx.save();
      ctx.filter = 'blur(28px)';
      const mist1 = ctx.createRadialGradient(w * 0.52, horizon * 0.72, 20, w * 0.52, horizon * 0.72, w * 0.45);
      mist1.addColorStop(0, 'rgba(255, 255, 255, 0.48)');
      mist1.addColorStop(1, 'rgba(255, 255, 255, 0)');
      ctx.fillStyle = mist1;
      ctx.fillRect(0, 0, w, horizon);
      ctx.restore();

      // Calm long-exposure ocean
      const sea = ctx.createLinearGradient(0, horizon, 0, h);
      sea.addColorStop(0, '#C7CACB');
      sea.addColorStop(0.14, '#929699');
      sea.addColorStop(0.55, '#62666A');
      sea.addColorStop(1, '#3B3E42');
      ctx.fillStyle = sea;
      ctx.fillRect(0, horizon, w, h - horizon);

      // Delicate horizontal wave ripples fading with perspective
      const rand = mulberry32(404);
      for (let i = 0; i < 190; i++) {
        const t = Math.pow(rand(), 1.55);
        const y = horizon + 3 + t * (h - horizon - 8);
        const len = 30 + rand() * (140 + t * 240);
        const x = rand() * w - len * 0.3;
        const alpha = 0.03 + (1 - t) * 0.08;
        ctx.fillStyle = rand() > 0.45 ? `rgba(245,246,248,${alpha})` : `rgba(25,28,32,${alpha * 0.9})`;
        ctx.fillRect(x, y, len, 1 + t * 2.2);
      }

      // Soft horizon fog veil blending sea & sky
      ctx.save();
      ctx.filter = 'blur(14px)';
      ctx.fillStyle = 'rgba(225, 226, 224, 0.52)';
      ctx.fillRect(0, horizon - 10, w, 20);
      ctx.restore();

      applyFilmFinish(ctx, w, h, { grain: 0.13, vignette: 0.36, bw: true });
    }

    // 03: Rain on Saint-Germain — Saul Leiter-inspired nocturnal bokeh & wet pavement reflections
    function renderRainSaintGermain(ctx, w, h) {
      // Deep Parisian rain twilight
      const bg = ctx.createLinearGradient(0, 0, 0, h);
      bg.addColorStop(0, '#0C121C');
      bg.addColorStop(0.48, '#161C24');
      bg.addColorStop(0.62, '#101318');
      bg.addColorStop(1, '#08090C');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);

      // Blurred Haussmann building silhouettes framing top sides
      ctx.save();
      ctx.filter = 'blur(8px)';
      ctx.fillStyle = '#090D14';
      ctx.fillRect(0, 0, w * 0.24, h * 0.62);
      ctx.fillRect(w * 0.78, 0, w * 0.22, h * 0.58);
      ctx.restore();

      // Luminous out-of-focus bokeh orbs (streetlamps, café windows, tail lights)
      const lights = [
        { x: 0.34, y: 0.24, r: 54, c: 'rgba(255, 198, 118, 0.78)', halo: 'rgba(230, 88, 48, 0.35)' },
        { x: 0.64, y: 0.29, r: 44, c: 'rgba(255, 214, 146, 0.72)', halo: 'rgba(235, 96, 52, 0.28)' },
        { x: 0.48, y: 0.46, r: 34, c: 'rgba(255, 86, 62, 0.85)', halo: 'rgba(255, 42, 32, 0.4)' },
        { x: 0.55, y: 0.47, r: 30, c: 'rgba(255, 92, 68, 0.82)', halo: 'rgba(255, 46, 36, 0.36)' },
        { x: 0.23, y: 0.42, r: 42, c: 'rgba(255, 174, 88, 0.75)', halo: 'rgba(240, 102, 42, 0.32)' },
        { x: 0.74, y: 0.44, r: 48, c: 'rgba(130, 215, 225, 0.55)', halo: 'rgba(72, 165, 190, 0.25)' },
        { x: 0.42, y: 0.36, r: 22, c: 'rgba(255, 232, 185, 0.72)', halo: 'rgba(255, 150, 80, 0.25)' },
        { x: 0.68, y: 0.38, r: 18, c: 'rgba(255, 100, 75, 0.65)', halo: 'rgba(220, 45, 35, 0.25)' },
        { x: 0.16, y: 0.52, r: 36, c: 'rgba(255, 185, 92, 0.68)', halo: 'rgba(230, 95, 40, 0.28)' },
        { x: 0.82, y: 0.51, r: 32, c: 'rgba(255, 204, 128, 0.64)', halo: 'rgba(230, 95, 40, 0.24)' }
      ];

      // Cinestill 800T halation glow
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      lights.forEach(l => {
        const gx = w * l.x, gy = h * l.y;
        const hal = ctx.createRadialGradient(gx, gy, l.r * 0.2, gx, gy, l.r * 2.8);
        hal.addColorStop(0, l.halo);
        hal.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = hal;
        ctx.beginPath();
        ctx.arc(gx, gy, l.r * 2.8, 0, Math.PI * 2);
        ctx.fill();
      });

      // Soft bokeh discs
      ctx.filter = 'blur(9px)';
      lights.forEach(l => {
        const gx = w * l.x, gy = h * l.y;
        ctx.fillStyle = l.c;
        ctx.beginPath();
        ctx.arc(gx, gy, l.r, 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.restore();

      // Wet street smeared vertical reflections
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.filter = 'blur(14px)';
      lights.forEach(l => {
        const gx = w * l.x;
        const refGrad = ctx.createLinearGradient(gx, h * 0.58, gx, h * 0.98);
        refGrad.addColorStop(0, l.c);
        refGrad.addColorStop(0.55, l.halo);
        refGrad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = refGrad;
        ctx.fillRect(gx - l.r * 0.7, h * 0.58, l.r * 1.4, h * 0.42);
      });
      ctx.restore();

      // Dark umbrella figure crossing in foreground silhouette
      ctx.save();
      ctx.filter = 'blur(3.5px)';
      ctx.fillStyle = '#07080B';
      // Umbrella dome
      ctx.beginPath();
      ctx.arc(w * 0.38, h * 0.65, w * 0.13, Math.PI * 1.04, Math.PI * 1.96, false);
      ctx.closePath();
      ctx.fill();
      // Coat silhouette
      ctx.beginPath();
      ctx.moveTo(w * 0.34, h * 0.65);
      ctx.lineTo(w * 0.42, h * 0.65);
      ctx.lineTo(w * 0.44, h * 0.92);
      ctx.lineTo(w * 0.32, h * 0.92);
      ctx.closePath();
      ctx.fill();
      ctx.restore();

      // Delicate raindrop streaks on glass
      const rand = mulberry32(800);
      ctx.save();
      for (let i = 0; i < 65; i++) {
        const x = rand() * w;
        const y = rand() * h;
        const r = 1.5 + rand() * 5;
        ctx.fillStyle = `rgba(255, 240, 220, ${(0.04 + rand() * 0.12).toFixed(3)})`;
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();

      applyFilmFinish(ctx, w, h, { grain: 0.145, vignette: 0.45 });
    }

    // 04: Morning Shadow, Studio 4B — Warm lime plaster with Venetian blind sunlight & olive foliage shadow
    function renderMorningShadow(ctx, w, h) {
      // Base sunlit plaster wall
      const wall = ctx.createLinearGradient(0, 0, w, h);
      wall.addColorStop(0, '#E8DFD1');
      wall.addColorStop(0.55, '#DCD1BF');
      wall.addColorStop(1, '#C5B69F');
      ctx.fillStyle = wall;
      ctx.fillRect(0, 0, w, h);

      // Shadowed corner at left
      const corner = ctx.createLinearGradient(0, 0, w * 0.24, 0);
      corner.addColorStop(0, 'rgba(62, 52, 42, 0.36)');
      corner.addColorStop(1, 'rgba(62, 52, 42, 0)');
      ctx.fillStyle = corner;
      ctx.fillRect(0, 0, w * 0.28, h);

      // Golden louvered light beams projected diagonally
      ctx.save();
      ctx.filter = 'blur(6px)';
      ctx.fillStyle = 'rgba(72, 58, 46, 0.46)';
      ctx.fillRect(0, 0, w, h);

      ctx.globalCompositeOperation = 'screen';
      const slats = 11;
      for (let i = 0; i < slats; i++) {
        const yStart = h * (0.08 + i * 0.072);
        const beam = ctx.createLinearGradient(w * 0.12, yStart, w * 0.92, yStart + h * 0.22);
        beam.addColorStop(0, 'rgba(255, 226, 174, 0.42)');
        beam.addColorStop(0.5, 'rgba(255, 214, 152, 0.54)');
        beam.addColorStop(1, 'rgba(255, 200, 130, 0.14)');
        ctx.fillStyle = beam;
        ctx.beginPath();
        ctx.moveTo(w * 0.14, yStart);
        ctx.lineTo(w * 0.9, yStart + h * 0.19);
        ctx.lineTo(w * 0.9, yStart + h * 0.235);
        ctx.lineTo(w * 0.14, yStart + h * 0.045);
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();

      // Soft botanical branch & leaf shadow
      ctx.save();
      ctx.filter = 'blur(9px)';
      ctx.strokeStyle = 'rgba(46, 36, 28, 0.48)';
      ctx.fillStyle = 'rgba(46, 36, 28, 0.44)';
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(w * 1.05, h * 0.18);
      ctx.quadraticCurveTo(w * 0.62, h * 0.36, w * 0.28, h * 0.68);
      ctx.stroke();

      const leaves = [
        [0.78, 0.28, -0.5, 58, 16], [0.68, 0.36, 0.4, 62, 18], [0.56, 0.42, -0.6, 54, 15],
        [0.48, 0.51, 0.35, 60, 17], [0.39, 0.58, -0.5, 48, 14], [0.32, 0.65, 0.25, 44, 13],
        [0.72, 0.24, -0.9, 50, 14], [0.52, 0.38, -0.8, 45, 13]
      ];
      leaves.forEach(([lx, ly, ang, rx, ry]) => {
        ctx.save();
        ctx.translate(w * lx, h * ly);
        ctx.rotate(ang);
        ctx.beginPath();
        ctx.ellipse(0, 0, rx, ry, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      });
      ctx.restore();

      // Minimal wooden table edge at bottom
      const table = ctx.createLinearGradient(0, h * 0.87, 0, h);
      table.addColorStop(0, '#8A6F56');
      table.addColorStop(1, '#584434');
      ctx.fillStyle = table;
      ctx.fillRect(0, h * 0.88, w, h * 0.12);

      // Subtle ceramic cup silhouette on table
      ctx.fillStyle = '#E5DAC8';
      ctx.beginPath();
      ctx.roundRect(w * 0.66, h * 0.785, w * 0.08, h * 0.098, [4, 4, 12, 12]);
      ctx.fill();
      ctx.fillStyle = 'rgba(46, 36, 28, 0.22)';
      ctx.fillRect(w * 0.66, h * 0.785, w * 0.035, h * 0.098);

      applyFilmFinish(ctx, w, h, { grain: 0.085, vignette: 0.25, warmTint: 'rgba(255, 224, 182, 0.1)' });
    }

    // 05: Dune Ridge, Almería — Graphic desert dunes in warm sunset & cool shadow
    function renderDuneRidge(ctx, w, h) {
      // Clear warm evening sky
      const sky = ctx.createLinearGradient(0, 0, 0, h * 0.45);
      sky.addColorStop(0, '#5A6E8C');
      sky.addColorStop(0.5, '#A69596');
      sky.addColorStop(1, '#E6BDA0');
      ctx.fillStyle = sky;
      ctx.fillRect(0, 0, w, h * 0.48);

      // Distant soft dune band
      ctx.fillStyle = '#C99C7C';
      ctx.beginPath();
      ctx.moveTo(0, h * 0.46);
      ctx.quadraticCurveTo(w * 0.28, h * 0.34, w * 0.56, h * 0.42);
      ctx.quadraticCurveTo(w * 0.82, h * 0.49, w, h * 0.39);
      ctx.lineTo(w, h);
      ctx.lineTo(0, h);
      ctx.closePath();
      ctx.fill();

      // Main sculptural dune sunlit face
      const sunFace = ctx.createLinearGradient(0, h * 0.36, w * 0.7, h);
      sunFace.addColorStop(0, '#E8AE7B');
      sunFace.addColorStop(0.5, '#D18757');
      sunFace.addColorStop(1, '#9E5D3C');
      ctx.fillStyle = sunFace;
      ctx.beginPath();
      ctx.moveTo(0, h * 0.52);
      ctx.bezierCurveTo(w * 0.24, h * 0.32, w * 0.52, h * 0.44, w, h * 0.54);
      ctx.lineTo(w, h);
      ctx.lineTo(0, h);
      ctx.closePath();
      ctx.fill();

      // Deep violet-umber shadow face divided by razor S-curve ridge
      const shadowFace = ctx.createLinearGradient(w * 0.4, h * 0.4, w, h);
      shadowFace.addColorStop(0, '#5E4246');
      shadowFace.addColorStop(0.55, '#3A2830');
      shadowFace.addColorStop(1, '#21181F');
      ctx.fillStyle = shadowFace;
      ctx.beginPath();
      ctx.moveTo(w * 0.34, h * 0.395);
      ctx.bezierCurveTo(w * 0.52, h * 0.52, w * 0.44, h * 0.72, w * 0.68, h);
      ctx.lineTo(w, h);
      ctx.lineTo(w, h * 0.54);
      ctx.bezierCurveTo(w * 0.64, h * 0.46, w * 0.46, h * 0.38, w * 0.34, h * 0.395);
      ctx.closePath();
      ctx.fill();

      // Subtle wind-blown sand ripples on sunlit slope
      ctx.save();
      ctx.strokeStyle = 'rgba(255, 224, 186, 0.14)';
      ctx.lineWidth = 1.5;
      for (let i = 0; i < 24; i++) {
        const y = h * (0.56 + i * 0.018);
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.quadraticCurveTo(w * 0.22, y - 8, w * (0.42 + i * 0.006), y + 4);
        ctx.stroke();
      }
      ctx.restore();

      applyFilmFinish(ctx, w, h, { grain: 0.1, vignette: 0.32 });
    }

    // 06: Stairwell Study IV — Monochrome architectural spiral & dramatic skylight beams
    function renderStairwellStudy(ctx, w, h) {
      ctx.fillStyle = '#181818';
      ctx.fillRect(0, 0, w, h);

      // Concrete stairwell curved walls
      const wall = ctx.createRadialGradient(w * 0.54, h * 0.26, 20, w * 0.5, h * 0.45, h * 0.72);
      wall.addColorStop(0, '#EDEDEB');
      wall.addColorStop(0.28, '#9A9A98');
      wall.addColorStop(0.65, '#3E3E3E');
      wall.addColorStop(1, '#121212');
      ctx.fillStyle = wall;
      ctx.fillRect(0, 0, w, h);

      // Concentric architectural spiral tiers
      const tiers = 7;
      for (let i = 0; i < tiers; i++) {
        const t = i / tiers;
        const r = Math.min(w, h) * (0.64 - t * 0.48);
        const cx = w * (0.52 + t * 0.04);
        const cy = h * (0.52 - t * 0.16);

        ctx.save();
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.lineWidth = 34 - t * 18;
        ctx.strokeStyle = `rgb(${225 - i * 24}, ${225 - i * 24}, ${225 - i * 24})`;
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(cx, cy, r - (18 - t * 9), 0, Math.PI * 2);
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#111111';
        ctx.stroke();
        ctx.restore();
      }

      // Dramatic diagonal shaft of skylight
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.filter = 'blur(14px)';
      const beam = ctx.createLinearGradient(w * 0.65, 0, w * 0.2, h * 0.95);
      beam.addColorStop(0, 'rgba(255,255,255,0.62)');
      beam.addColorStop(0.5, 'rgba(220,220,220,0.22)');
      beam.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = beam;
      ctx.beginPath();
      ctx.moveTo(w * 0.56, 0);
      ctx.lineTo(w * 0.88, 0);
      ctx.lineTo(w * 0.36, h);
      ctx.lineTo(w * 0.04, h);
      ctx.closePath();
      ctx.fill();
      ctx.restore();

      applyFilmFinish(ctx, w, h, { grain: 0.135, vignette: 0.42, bw: true });
    }

    // 07: Last Ferry, Tagus River — Deep indigo night estuary & vertical light reflections
    function renderLastFerry(ctx, w, h) {
      const horizon = h * 0.46;

      // Deep nocturnal indigo sky
      const sky = ctx.createLinearGradient(0, 0, 0, horizon);
      sky.addColorStop(0, '#090E1A');
      sky.addColorStop(0.65, '#131E33');
      sky.addColorStop(1, '#263348');
      ctx.fillStyle = sky;
      ctx.fillRect(0, 0, w, horizon);

      // Distant Lisbon hillside silhouette
      ctx.fillStyle = '#0D131F';
      ctx.beginPath();
      ctx.moveTo(0, horizon);
      ctx.lineTo(0, horizon - 28);
      ctx.quadraticCurveTo(w * 0.22, horizon - 58, w * 0.48, horizon - 32);
      ctx.quadraticCurveTo(w * 0.74, horizon - 62, w, horizon - 24);
      ctx.lineTo(w, horizon);
      ctx.closePath();
      ctx.fill();

      // Dark estuary water
      const water = ctx.createLinearGradient(0, horizon, 0, h);
      water.addColorStop(0, '#131C2B');
      water.addColorStop(0.5, '#0B111C');
      water.addColorStop(1, '#06080E');
      ctx.fillStyle = water;
      ctx.fillRect(0, horizon, w, h - horizon);

      // City light beads & shimmering vertical water reflections
      const rand = mulberry32(777);
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      for (let i = 0; i < 95; i++) {
        const x = rand() * w;
        const y = horizon - 4 - rand() * 34;
        const isWarm = rand() > 0.2;
        const col = isWarm ? 'rgba(255, 198, 122,' : 'rgba(170, 215, 255,';
        const r = 1 + rand() * 2.2;

        ctx.fillStyle = `${col} 0.9)`;
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fill();

        // Shimmering vertical reflection streaks on water
        if (rand() > 0.45) {
          const refLen = 40 + rand() * (h * 0.44);
          for (let s = 0; s < refLen; s += 5) {
            const fade = 1 - s / refLen;
            const jitter = (rand() - 0.5) * (3 + s * 0.04);
            ctx.fillStyle = `${col} ${(fade * 0.34).toFixed(3)})`;
            ctx.fillRect(x + jitter - r * 1.4, horizon + 4 + s, r * 2.8 + s * 0.03, 2.2);
          }
        }
      }
      ctx.restore();

      // Subtle atmospheric river mist along horizon
      ctx.save();
      ctx.filter = 'blur(16px)';
      ctx.fillStyle = 'rgba(130, 155, 185, 0.16)';
      ctx.fillRect(0, horizon - 12, w, 26);
      ctx.restore();

      applyFilmFinish(ctx, w, h, { grain: 0.14, vignette: 0.4 });
    }

    // 08: Ceramic & Dusk — Plaster architectural alcove, sculptural vessel & sunset light
    function renderCeramicDusk(ctx, w, h) {
      // Soft lime-plaster wall
      const wall = ctx.createLinearGradient(0, 0, w, h);
      wall.addColorStop(0, '#D7C8B7');
      wall.addColorStop(0.6, '#C4B19E');
      wall.addColorStop(1, '#9E8A77');
      ctx.fillStyle = wall;
      ctx.fillRect(0, 0, w, h);

      // Recessed arched niche
      const nx = w * 0.22, nw = w * 0.56, ny = h * 0.16, nh = h * 0.66;
      const nicheGrad = ctx.createLinearGradient(nx, ny, nx + nw, ny + nh);
      nicheGrad.addColorStop(0, '#7B6758');
      nicheGrad.addColorStop(0.55, '#9F8874');
      nicheGrad.addColorStop(1, '#E4B88F');
      ctx.fillStyle = nicheGrad;
      ctx.beginPath();
      ctx.moveTo(nx, ny + nh);
      ctx.lineTo(nx, ny + nw * 0.5);
      ctx.arc(nx + nw * 0.5, ny + nw * 0.5, nw * 0.5, Math.PI, 0, false);
      ctx.lineTo(nx + nw, ny + nh);
      ctx.closePath();
      ctx.fill();

      // Raking golden sunset slice entering right side of alcove
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(nx, ny + nh);
      ctx.lineTo(nx, ny + nw * 0.5);
      ctx.arc(nx + nw * 0.5, ny + nw * 0.5, nw * 0.5, Math.PI, 0, false);
      ctx.lineTo(nx + nw, ny + nh);
      ctx.closePath();
      ctx.clip();

      const raking = ctx.createLinearGradient(nx + nw * 0.35, ny, nx + nw, ny + nh);
      raking.addColorStop(0, 'rgba(255, 206, 148, 0)');
      raking.addColorStop(0.4, 'rgba(255, 202, 140, 0.52)');
      raking.addColorStop(1, 'rgba(240, 152, 92, 0.68)');
      ctx.fillStyle = raking;
      ctx.beginPath();
      ctx.moveTo(nx + nw * 0.42, ny);
      ctx.lineTo(nx + nw, ny);
      ctx.lineTo(nx + nw, ny + nh);
      ctx.lineTo(nx + nw * 0.15, ny + nh);
      ctx.closePath();
      ctx.fill();
      ctx.restore();

      // Stone shelf at bottom of niche
      ctx.fillStyle = '#B8A28E';
      ctx.fillRect(nx - 6, ny + nh, nw + 12, 16);
      ctx.fillStyle = 'rgba(42, 32, 24, 0.32)';
      ctx.fillRect(nx - 6, ny + nh + 16, nw + 12, 12);

      // Soft cast shadow of vessel on left
      ctx.save();
      ctx.filter = 'blur(10px)';
      ctx.fillStyle = 'rgba(48, 34, 24, 0.42)';
      ctx.beginPath();
      ctx.ellipse(w * 0.42, ny + nh - 4, w * 0.14, 14, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // Sculptural stoneware vessel
      const vx = w * 0.52, base = ny + nh;
      const vesselGrad = ctx.createLinearGradient(vx - w * 0.13, base - h * 0.3, vx + w * 0.13, base);
      vesselGrad.addColorStop(0, '#5A4336');
      vesselGrad.addColorStop(0.55, '#8F6B56');
      vesselGrad.addColorStop(0.88, '#D7A47C');
      vesselGrad.addColorStop(1, '#E8C09B');
      ctx.fillStyle = vesselGrad;
      ctx.beginPath();
      ctx.moveTo(vx - w * 0.065, base);
      ctx.bezierCurveTo(vx - w * 0.15, base - h * 0.1, vx - w * 0.13, base - h * 0.25, vx - w * 0.042, base - h * 0.31);
      ctx.lineTo(vx - w * 0.048, base - h * 0.36);
      ctx.lineTo(vx + w * 0.048, base - h * 0.36);
      ctx.lineTo(vx + w * 0.042, base - h * 0.31);
      ctx.bezierCurveTo(vx + w * 0.13, base - h * 0.25, vx + w * 0.15, base - h * 0.1, vx + w * 0.065, base);
      ctx.closePath();
      ctx.fill();

      applyFilmFinish(ctx, w, h, { grain: 0.09, vignette: 0.3, warmTint: 'rgba(255, 200, 150, 0.08)' });
    }

    // 09: Glass Atrium, Dusk — Cool cobalt modernist grid with three glowing amber windows
    function renderGlassAtrium(ctx, w, h) {
      // Cobalt blue hour reflection across glass curtain wall
      const base = ctx.createLinearGradient(0, 0, w, h);
      base.addColorStop(0, '#1D3352');
      base.addColorStop(0.5, '#15253D');
      base.addColorStop(1, '#0E1829');
      ctx.fillStyle = base;
      ctx.fillRect(0, 0, w, h);

      const cols = 5, rows = 6;
      const cw = w / cols, ch = h / rows;
      const lit = new Set(['1,2', '3,3', '2,4']);

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const x = c * cw, y = r * ch;
          const key = `${c},${r}`;
          if (lit.has(key)) {
            const g = ctx.createLinearGradient(x, y, x, y + ch);
            g.addColorStop(0, '#F5CE8B');
            g.addColorStop(0.5, '#E4A862');
            g.addColorStop(1, '#B8763C');
            ctx.fillStyle = g;
            ctx.fillRect(x + 4, y + 4, cw - 8, ch - 8);

            // Subtle interior desk/ceiling silhouette
            ctx.fillStyle = 'rgba(72, 42, 24, 0.22)';
            ctx.fillRect(x + 4, y + ch * 0.72, cw - 8, ch * 0.24);
          } else {
            // Subtle sky reflection variance per pane
            const pane = ctx.createLinearGradient(x, y, x + cw, y + ch);
            const shift = ((c + r) % 3) * 8;
            pane.addColorStop(0, `rgb(${32 + shift}, ${56 + shift}, ${88 + shift})`);
            pane.addColorStop(1, `rgb(${16 + shift / 2}, ${30 + shift / 2}, ${52 + shift / 2})`);
            ctx.fillStyle = pane;
            ctx.fillRect(x + 4, y + 4, cw - 8, ch - 8);
          }
        }
      }

      // Warm halation glow around lit windows
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      lit.forEach(key => {
        const [c, r] = key.split(',').map(Number);
        const cx = (c + 0.5) * cw, cy = (r + 0.5) * ch;
        const glow = ctx.createRadialGradient(cx, cy, 10, cx, cy, cw * 1.4);
        glow.addColorStop(0, 'rgba(255, 168, 86, 0.34)');
        glow.addColorStop(1, 'rgba(255, 120, 60, 0)');
        ctx.fillStyle = glow;
        ctx.fillRect(0, 0, w, h);
      });
      ctx.restore();

      // Crisp dark steel mullions
      ctx.fillStyle = '#090D14';
      for (let c = 0; c <= cols; c++) ctx.fillRect(c * cw - 4, 0, 8, h);
      for (let r = 0; r <= rows; r++) ctx.fillRect(0, r * ch - 4, w, 8);

      applyFilmFinish(ctx, w, h, { grain: 0.115, vignette: 0.34 });
    }

    // 10: Salt Flats at Twilight — Rosy dusk reflected across glass-like Camargue flats
    function renderSaltFlats(ctx, w, h) {
      const horizon = h * 0.52;

      const sky = ctx.createLinearGradient(0, 0, 0, horizon);
      sky.addColorStop(0, '#3C4866');
      sky.addColorStop(0.38, '#7A6882');
      sky.addColorStop(0.74, '#C88D8C');
      sky.addColorStop(1, '#F0C5A2');
      ctx.fillStyle = sky;
      ctx.fillRect(0, 0, w, horizon);

      // Soft cirrus cloud streaks
      ctx.save();
      ctx.filter = 'blur(12px)';
      ctx.fillStyle = 'rgba(255, 224, 198, 0.32)';
      ctx.beginPath();
      ctx.ellipse(w * 0.32, horizon * 0.54, w * 0.28, 12, -0.02, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(w * 0.72, horizon * 0.42, w * 0.24, 9, 0.01, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // Distant low ridge
      ctx.fillStyle = '#3A3242';
      ctx.beginPath();
      ctx.moveTo(0, horizon);
      ctx.lineTo(0, horizon - 10);
      ctx.quadraticCurveTo(w * 0.3, horizon - 24, w * 0.62, horizon - 12);
      ctx.quadraticCurveTo(w * 0.85, horizon - 19, w, horizon - 8);
      ctx.lineTo(w, horizon);
      ctx.closePath();
      ctx.fill();

      // Mirror-like shallow salt water reflecting sky
      const mirror = ctx.createLinearGradient(0, horizon, 0, h);
      mirror.addColorStop(0, '#E3B698');
      mirror.addColorStop(0.32, '#B68286');
      mirror.addColorStop(0.7, '#6A5B74');
      mirror.addColorStop(1, '#2E344B');
      ctx.fillStyle = mirror;
      ctx.fillRect(0, horizon, w, h - horizon);

      // Subtle salt-crust shoals & wooden marker posts
      ctx.fillStyle = 'rgba(38, 30, 42, 0.55)';
      ctx.beginPath();
      ctx.ellipse(w * 0.18, h * 0.78, w * 0.22, 8, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(w * 0.82, h * 0.69, w * 0.18, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Three minimalist wooden tidal stakes & their reflections
      const stakes = [
        { x: w * 0.36, y: horizon + 26, len: 42 },
        { x: w * 0.44, y: horizon + 46, len: 54 },
        { x: w * 0.54, y: horizon + 74, len: 68 }
      ];
      stakes.forEach(s => {
        ctx.fillStyle = '#241E29';
        ctx.fillRect(s.x - 2, s.y - s.len, 4, s.len);
        ctx.fillStyle = 'rgba(36, 30, 41, 0.38)';
        ctx.fillRect(s.x - 2, s.y, 4, s.len * 0.85);
      });

      applyFilmFinish(ctx, w, h, { grain: 0.085, vignette: 0.3 });
    }

    // 11: Solitary Figure, Prado — Fan Ho-inspired dramatic backlit monochrome mist & shadow
    function renderSolitaryFigure(ctx, w, h) {
      // Luminous backlit haze
      const bg = ctx.createRadialGradient(w * 0.72, h * 0.24, 30, w * 0.65, h * 0.35, h * 0.92);
      bg.addColorStop(0, '#F5F4F0');
      bg.addColorStop(0.4, '#BFBFBC');
      bg.addColorStop(0.8, '#585858');
      bg.addColorStop(1, '#1E1E1E');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);

      // Towering dark colonnade silhouette on left
      ctx.fillStyle = '#141414';
      ctx.fillRect(0, 0, w * 0.26, h);
      ctx.fillStyle = '#242424';
      ctx.fillRect(w * 0.26, 0, w * 0.06, h * 0.78);

      // Sunbeams cutting through mist from top-right
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.filter = 'blur(18px)';
      const ray = ctx.createLinearGradient(w * 0.85, 0, w * 0.28, h * 0.85);
      ray.addColorStop(0, 'rgba(255,255,255,0.65)');
      ray.addColorStop(0.6, 'rgba(240,240,240,0.22)');
      ray.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = ray;
      ctx.beginPath();
      ctx.moveTo(w * 0.56, 0);
      ctx.lineTo(w, 0);
      ctx.lineTo(w * 0.58, h);
      ctx.lineTo(w * 0.18, h);
      ctx.closePath();
      ctx.fill();
      ctx.restore();

      // Stone pavement plane
      const ground = ctx.createLinearGradient(0, h * 0.72, 0, h);
      ground.addColorStop(0, '#969694');
      ground.addColorStop(0.4, '#5C5C5A');
      ground.addColorStop(1, '#262625');
      ctx.fillStyle = ground;
      ctx.fillRect(0, h * 0.73, w, h * 0.27);

      // Long dramatic cast shadow stretching bottom-left
      ctx.save();
      ctx.filter = 'blur(4px)';
      ctx.fillStyle = 'rgba(12, 12, 12, 0.75)';
      ctx.beginPath();
      ctx.moveTo(w * 0.63, h * 0.76);
      ctx.lineTo(w * 0.66, h * 0.76);
      ctx.lineTo(w * 0.22, h);
      ctx.lineTo(w * 0.08, h);
      ctx.closePath();
      ctx.fill();
      ctx.restore();

      // Solitary backlit figure silhouette
      ctx.fillStyle = '#111111';
      // Head
      ctx.beginPath();
      ctx.arc(w * 0.645, h * 0.615, w * 0.017, 0, Math.PI * 2);
      ctx.fill();
      // Long coat torso
      ctx.beginPath();
      ctx.moveTo(w * 0.628, h * 0.635);
      ctx.lineTo(w * 0.662, h * 0.635);
      ctx.lineTo(w * 0.672, h * 0.725);
      ctx.lineTo(w * 0.618, h * 0.725);
      ctx.closePath();
      ctx.fill();
      // Legs in stride
      ctx.fillRect(w * 0.63, h * 0.722, w * 0.011, h * 0.042);
      ctx.fillRect(w * 0.649, h * 0.722, w * 0.011, h * 0.04);

      applyFilmFinish(ctx, w, h, { grain: 0.12, vignette: 0.42, bw: true });
    }

    // 12: Laundromat, Rua da Rosa — Cool turquoise storefront spilling onto dark cobblestones
    function renderLaundromatNight(ctx, w, h) {
      // Deep charcoal facade
      ctx.fillStyle = '#0D1014';
      ctx.fillRect(0, 0, w, h);

      // Storefront plaster facade
      const wall = ctx.createLinearGradient(0, 0, w, h * 0.72);
      wall.addColorStop(0, '#1B2127');
      wall.addColorStop(1, '#121519');
      ctx.fillStyle = wall;
      ctx.fillRect(0, 0, w, h * 0.72);

      // Glowing turquoise laundromat window
      const wx = w * 0.2, wy = h * 0.18, ww = w * 0.48, wh = h * 0.52;
      const winGrad = ctx.createLinearGradient(wx, wy, wx, wy + wh);
      winGrad.addColorStop(0, '#D4FFF8');
      winGrad.addColorStop(0.45, '#7DE0D8');
      winGrad.addColorStop(1, '#398F96');
      ctx.fillStyle = winGrad;
      ctx.fillRect(wx, wy, ww, wh);

      // Row of circular drum machines inside window
      for (let i = 0; i < 4; i++) {
        const mx = wx + ww * (0.14 + i * 0.24);
        const my = wy + wh * 0.72;
        ctx.fillStyle = '#2B5B64';
        ctx.fillRect(mx - 34, my - 46, 68, 92);
        ctx.beginPath();
        ctx.arc(mx, my, 22, 0, Math.PI * 2);
        ctx.fillStyle = '#122930';
        ctx.fill();
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#A7ECE8';
        ctx.stroke();
      }

      // Window mullions
      ctx.fillStyle = '#0D1115';
      ctx.fillRect(wx + ww * 0.5 - 4, wy, 8, wh);

      // Warm tungsten doorway next door
      const dx = w * 0.76, dy = h * 0.24, dw = w * 0.12, dh = h * 0.48;
      const door = ctx.createLinearGradient(dx, dy, dx, dy + dh);
      door.addColorStop(0, '#FFCC82');
      door.addColorStop(1, '#C96F3A');
      ctx.fillStyle = door;
      ctx.fillRect(dx, dy, dw, dh);

      // Wet cobblestone street catching turquoise & amber spill
      const street = ctx.createLinearGradient(0, h * 0.72, 0, h);
      street.addColorStop(0, '#12161B');
      street.addColorStop(1, '#080A0D');
      ctx.fillStyle = street;
      ctx.fillRect(0, h * 0.72, w, h * 0.28);

      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.filter = 'blur(26px)';
      const spillCyan = ctx.createRadialGradient(wx + ww * 0.5, h * 0.72, 20, wx + ww * 0.5, h * 0.86, ww * 0.75);
      spillCyan.addColorStop(0, 'rgba(115, 235, 225, 0.52)');
      spillCyan.addColorStop(1, 'rgba(40, 140, 150, 0)');
      ctx.fillStyle = spillCyan;
      ctx.fillRect(0, h * 0.65, w, h * 0.35);

      const spillWarm = ctx.createRadialGradient(dx + dw * 0.5, h * 0.72, 10, dx + dw * 0.5, h * 0.85, w * 0.22);
      spillWarm.addColorStop(0, 'rgba(255, 165, 92, 0.46)');
      spillWarm.addColorStop(1, 'rgba(220, 80, 40, 0)');
      ctx.fillStyle = spillWarm;
      ctx.fillRect(0, h * 0.65, w, h * 0.35);

      // Cinestill red halation along top fluorescent tube
      const hal = ctx.createRadialGradient(wx + ww * 0.5, wy + 24, 10, wx + ww * 0.5, wy + 24, ww * 0.55);
      hal.addColorStop(0, 'rgba(255, 95, 72, 0.28)');
      hal.addColorStop(1, 'rgba(255, 60, 40, 0)');
      ctx.fillStyle = hal;
      ctx.fillRect(0, 0, w, h * 0.5);
      ctx.restore();

      // Subtle cobblestone specular highlights
      const rand = mulberry32(1212);
      for (let i = 0; i < 160; i++) {
        const cx = rand() * w;
        const cy = h * (0.74 + rand() * 0.25);
        const nearCyan = cx > wx - 40 && cx < wx + ww + 40;
        const nearWarm = cx > dx - 40 && cx < dx + dw + 60;
        if (!nearCyan && !nearWarm) continue;
        ctx.fillStyle = nearCyan ? 'rgba(165, 248, 240, 0.14)' : 'rgba(255, 195, 130, 0.14)';
        ctx.fillRect(cx, cy, 8 + rand() * 14, 2 + rand() * 3);
      }

      applyFilmFinish(ctx, w, h, { grain: 0.145, vignette: 0.42 });
    }

    // Studio Still-Life Portrait for About Section (Hasselblad camera silhouette & window light)
    function renderStudioPortrait() {
      const c = document.createElement('canvas');
      c.width = 760;
      c.height = 950;
      const ctx = c.getContext('2d');
      const w = c.width, h = c.height;

      const bg = ctx.createLinearGradient(0, 0, w, h);
      bg.addColorStop(0, '#D4D2CC');
      bg.addColorStop(0.55, '#9A9790');
      bg.addColorStop(1, '#3D3B38');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);

      // Soft studio window light from upper-left
      ctx.save();
      ctx.filter = 'blur(24px)';
      const win = ctx.createLinearGradient(0, 0, w * 0.78, h * 0.75);
      win.addColorStop(0, 'rgba(255,255,255,0.68)');
      win.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = win;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(w * 0.56, 0);
      ctx.lineTo(w * 0.9, h * 0.85);
      ctx.lineTo(0, h * 0.62);
      ctx.closePath();
      ctx.fill();
      ctx.restore();

      // Darkroom table surface
      ctx.fillStyle = '#252422';
      ctx.fillRect(0, h * 0.74, w, h * 0.26);

      // Minimalist medium-format camera silhouette resting on table
      const cx = w * 0.48, ty = h * 0.74;
      // Shadow
      ctx.save();
      ctx.filter = 'blur(10px)';
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.beginPath();
      ctx.ellipse(cx + 32, ty + 10, 125, 16, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // Camera body (Hasselblad cubic silhouette)
      ctx.fillStyle = '#181817';
      ctx.fillRect(cx - 72, ty - 134, 144, 134);
      // Chrome rim accent
      ctx.fillStyle = '#A8A6A0';
      ctx.fillRect(cx - 72, ty - 134, 144, 6);
      ctx.fillRect(cx - 72, ty - 10, 144, 4);
      // Waist-level viewfinder hood
      ctx.fillStyle = '#232321';
      ctx.beginPath();
      ctx.moveTo(cx - 64, ty - 134);
      ctx.lineTo(cx - 52, ty - 188);
      ctx.lineTo(cx + 52, ty - 188);
      ctx.lineTo(cx + 64, ty - 134);
      ctx.closePath();
      ctx.fill();
      // Lens barrel
      ctx.fillStyle = '#111110';
      ctx.fillRect(cx + 72, ty - 112, 68, 86);
      ctx.fillStyle = '#82807A';
      ctx.fillRect(cx + 96, ty - 112, 8, 86);
      ctx.fillRect(cx + 128, ty - 110, 5, 82);

      // Leaning framed print against background wall
      ctx.strokeStyle = 'rgba(24,24,22,0.55)';
      ctx.lineWidth = 8;
      ctx.strokeRect(w * 0.14, h * 0.22, w * 0.52, h * 0.52);

      applyFilmFinish(ctx, w, h, { grain: 0.13, vignette: 0.38, bw: true });
      return c.toDataURL('image/jpeg', 0.9);
    }

    /* --------------------------------------------------------------------------
       PRE-RENDER & CACHE ALL PLATES (INSTANT SWITCHING ACROSS VIEWS)
       -------------------------------------------------------------------------- */
    function buildArchive() {
      const offscreen = document.createElement('canvas');
      PLATES.forEach(plate => {
        offscreen.width = plate.width;
        offscreen.height = plate.height;
        const ctx = offscreen.getContext('2d', { willReadFrequently: true });
        ctx.clearRect(0, 0, plate.width, plate.height);
        plate.render(ctx, plate.width, plate.height);
        plate.histogram = computeHistogram(ctx, plate.width, plate.height);
        plate.src = offscreen.toDataURL('image/jpeg', 0.91);
      });
    }

    /* --------------------------------------------------------------------------
       APPLICATION STATE & INTERACTIVITY
       -------------------------------------------------------------------------- */
    const state = {
      category: 'all',
      view: 'editorial',
      heroIdx: 0,
      lightboxIdx: 0,
      lightboxOpen: false,
      zoomed: false,
      drawerOpen: true,
      filteredPlates: []
    };

    const featuredPlates = PLATES.filter(p => p.featured);

    function showToast(msg) {
      const toast = document.getElementById('toast');
      toast.textContent = msg;
      toast.classList.add('visible');
      clearTimeout(toast._timer);
      toast._timer = setTimeout(() => toast.classList.remove('visible'), 2600);
    }

    // Theme Switcher (Daylight / Darkroom)
    function initTheme() {
      const saved = localStorage.getItem('clara-theme');
      if (saved === 'darkroom') {
        document.documentElement.setAttribute('data-theme', 'darkroom');
        document.getElementById('themeLabel').textContent = 'Daylight';
      }

      document.getElementById('themeToggle').addEventListener('click', () => {
        const current = document.documentElement.getAttribute('data-theme');
        const next = current === 'darkroom' ? 'daylight' : 'darkroom';
        document.documentElement.setAttribute('data-theme', next);
        localStorage.setItem('clara-theme', next);
        document.getElementById('themeLabel').textContent = next === 'darkroom' ? 'Daylight' : 'Darkroom';
        showToast(next === 'darkroom' ? 'Darkroom mode enabled' : 'Daylight gallery mode enabled');
      });
    }

    // Hero Featured Frame Switcher
    function updateHeroPlate(idx, animate = true) {
      const frame = document.getElementById('heroFrame');
      const img = document.getElementById('heroImg');
      const title = document.getElementById('heroPlateTitle');
      const meta = document.getElementById('heroPlateMeta');

      state.heroIdx = (idx + featuredPlates.length) % featuredPlates.length;
      const plate = featuredPlates[state.heroIdx];
      const globalNum = String(PLATES.indexOf(plate) + 1).padStart(2, '0');

      const apply = () => {
        img.src = plate.src;
        img.alt = `${plate.title} — ${plate.location}`;
        title.textContent = plate.title;
        meta.textContent = `PLATE ${globalNum} / ${PLATES.length} · ${plate.location.split(',')[0].toUpperCase()} · ${plate.film.toUpperCase()}`;
        frame.classList.remove('switching');
      };

      if (animate) {
        frame.classList.add('switching');
        setTimeout(apply, 180);
      } else {
        apply();
      }
    }

    function initHero() {
      updateHeroPlate(0, false);
      document.getElementById('heroPrev').addEventListener('click', () => updateHeroPlate(state.heroIdx - 1));
      document.getElementById('heroNext').addEventListener('click', () => updateHeroPlate(state.heroIdx + 1));

      const openHeroInLightbox = () => {
        const plate = featuredPlates[state.heroIdx];
        openLightbox(plate.id);
      };
      const frame = document.getElementById('heroFrame');
      frame.addEventListener('click', openHeroInLightbox);
      frame.addEventListener('keydown', e => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          openHeroInLightbox();
        }
      });
    }

    // Render Gallery (Editorial Grid or Analog Contact Sheet)
    function renderGallery() {
      const mount = document.getElementById('galleryMount');
      state.filteredPlates = state.category === 'all'
        ? [...PLATES]
        : PLATES.filter(p => p.series === state.category);

      if (state.view === 'editorial') {
        const grid = document.createElement('div');
        grid.className = 'gallery-editorial';

        state.filteredPlates.forEach((plate, i) => {
          const card = document.createElement('article');
          const spanClass = state.category === 'all'
            ? plate.gridSpan
            : (i % 3 === 0 ? 'span-7' : (i % 3 === 1 ? 'span-5 offset-top' : 'span-6'));
          card.className = `photo-card ${spanClass}`;
          card.style.animationDelay = `${Math.min(i * 65, 360)}ms`;
          card.setAttribute('tabindex', '0');
          card.setAttribute('role', 'button');
          card.setAttribute('aria-label', `Inspect ${plate.title}`);

          const globalIdx = String(PLATES.indexOf(plate) + 1).padStart(2, '0');
          card.innerHTML = `
            <div class="photo-frame" style="aspect-ratio: ${plate.aspect};">
              <img src="${plate.src}" alt="${plate.title}, ${plate.location}" loading="lazy" />
              <span class="photo-hover-badge mono">Inspect Plate</span>
            </div>
            <div class="photo-meta">
              <div>
                <h3 class="photo-title">${plate.title}</h3>
                <div class="photo-sub">${plate.location} · ${plate.year}</div>
              </div>
              <span class="photo-index mono">${globalIdx} / ${plate.series}</span>
            </div>
          `;

          card.addEventListener('click', () => openLightbox(plate.id));
          card.addEventListener('keydown', e => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              openLightbox(plate.id);
            }
          });

          grid.appendChild(card);
        });

        mount.innerHTML = '';
        mount.appendChild(grid);
      } else {
        // Analog Darkroom Contact Sheet View
        const sheet = document.createElement('div');
        sheet.className = 'gallery-contact-sheet';

        const header = document.createElement('div');
        header.className = 'contact-sheet-header';
        header.innerHTML = `
          <span>ROLL #CM-2409 · ARCHIVE PROOF SHEET (${state.category.toUpperCase()})</span>
          <span>● RED MARKS INDICATE EXHIBITION SELECTS</span>
        `;
        sheet.appendChild(header);

        const grid = document.createElement('div');
        grid.className = 'contact-grid';

        const sprocketHTML = '<span></span>'.repeat(6);

        state.filteredPlates.forEach(plate => {
          const item = document.createElement('div');
          item.className = 'contact-frame';
          item.setAttribute('tabindex', '0');
          item.setAttribute('role', 'button');
          item.setAttribute('aria-label', `Inspect frame ${plate.frameCode}: ${plate.title}`);

          item.innerHTML = `
            <div class="sprockets top">${sprocketHTML}</div>
            <div class="contact-rebate">
              <span>◀ ${plate.frameCode}</span>
              <span>${plate.film.toUpperCase()}</span>
            </div>
            <div class="contact-img-wrap">
              <img src="${plate.src}" alt="${plate.title}" loading="lazy" />
              ${plate.editorPick ? '<div class="grease-mark" title="Exhibition Select"></div>' : ''}
            </div>
            <div class="contact-caption">
              <span>${plate.title}</span>
              <span>${plate.year}</span>
            </div>
            <div class="sprockets bottom">${sprocketHTML}</div>
          `;

          item.addEventListener('click', () => openLightbox(plate.id));
          item.addEventListener('keydown', e => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              openLightbox(plate.id);
            }
          });
          grid.appendChild(item);
        });

        sheet.appendChild(grid);
        mount.innerHTML = '';
        mount.appendChild(sheet);
      }
    }

    function initGalleryControls() {
      document.querySelectorAll('#filterPills .filter-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          document.querySelectorAll('#filterPills .filter-btn').forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          state.category = btn.dataset.category;
          renderGallery();
        });
      });

      document.querySelectorAll('.view-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          document.querySelectorAll('.view-btn').forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          state.view = btn.dataset.view;
          renderGallery();
        });
      });
    }

    /* --------------------------------------------------------------------------
       LIGHTBOX & LOUPE INSPECTOR
       -------------------------------------------------------------------------- */
    function drawHistogram(bins) {
      const canvas = document.getElementById('lbHistogram');
      const ctx = canvas.getContext('2d');
      const w = canvas.width, h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      // Subtle guide lines
      ctx.strokeStyle = 'rgba(234, 230, 223, 0.08)';
      ctx.lineWidth = 1;
      [0.25, 0.5, 0.75].forEach(x => {
        ctx.beginPath();
        ctx.moveTo(w * x, 0);
        ctx.lineTo(w * x, h);
        ctx.stroke();
      });

      // Smooth filled luminance curve
      const barW = w / bins.length;
      const grad = ctx.createLinearGradient(0, 0, w, 0);
      grad.addColorStop(0, 'rgba(130, 126, 118, 0.75)');
      grad.addColorStop(0.5, 'rgba(217, 133, 92, 0.85)');
      grad.addColorStop(1, 'rgba(240, 236, 228, 0.9)');
      ctx.fillStyle = grad;

      ctx.beginPath();
      ctx.moveTo(0, h);
      bins.forEach((val, i) => {
        const x = i * barW + barW * 0.5;
        const y = h - Math.max(2, val * (h - 6));
        ctx.lineTo(x, y);
      });
      ctx.lineTo(w, h);
      ctx.closePath();
      ctx.fill();
    }

    function updateLightboxContent() {
      const list = state.filteredPlates.length ? state.filteredPlates : PLATES;
      state.lightboxIdx = (state.lightboxIdx + list.length) % list.length;
      const plate = list[state.lightboxIdx];

      resetZoom();

      const img = document.getElementById('lbImg');
      img.src = plate.src;
      img.alt = `${plate.title} — ${plate.location}`;

      const idxStr = String(state.lightboxIdx + 1).padStart(2, '0');
      const totStr = String(list.length).padStart(2, '0');
      document.getElementById('lbCounter').textContent = `PLATE ${idxStr} / ${totStr} · ${plate.series.toUpperCase()}`;
      document.getElementById('lbSeries').textContent = plate.series;
      document.getElementById('lbTitle').textContent = plate.title;
      document.getElementById('lbLocation').textContent = `${plate.location} · ${plate.year}`;
      document.getElementById('lbNote').textContent = plate.note;
      document.getElementById('exifCamera').textContent = plate.camera;
      document.getElementById('exifLens').textContent = plate.lens;
      document.getElementById('exifExposure').textContent = plate.exposure;
      document.getElementById('exifFilm').textContent = plate.film;
      document.getElementById('exifTone').textContent = plate.tone;
      document.getElementById('lbEdition').textContent = `${plate.edition} · Hahnemühle Photo Rag 310gsm`;

      drawHistogram(plate.histogram);
    }

    function openLightbox(plateId) {
      const list = state.filteredPlates.length ? state.filteredPlates : PLATES;
      let idx = list.findIndex(p => p.id === plateId);
      if (idx === -1) {
        state.filteredPlates = [...PLATES];
        idx = PLATES.findIndex(p => p.id === plateId);
      }
      state.lightboxIdx = Math.max(0, idx);
      state.lightboxOpen = true;

      // Collapse drawer by default on narrow viewports so image stays front and center
      if (window.innerWidth < 1080) {
        state.drawerOpen = false;
        syncDrawerUI();
      }

      updateLightboxContent();
      const lb = document.getElementById('lightbox');
      lb.classList.add('open');
      lb.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    }

    function closeLightbox() {
      state.lightboxOpen = false;
      resetZoom();
      const lb = document.getElementById('lightbox');
      lb.classList.remove('open');
      lb.setAttribute('aria-hidden', 'true');
      document.body.style.overflow = '';
    }

    function syncDrawerUI() {
      const drawer = document.getElementById('lbDrawer');
      const btn = document.getElementById('lbInfoBtn');
      drawer.classList.toggle('collapsed', !state.drawerOpen);
      btn.classList.toggle('active', state.drawerOpen);
    }

    function toggleZoom(e) {
      state.zoomed = !state.zoomed;
      const wrap = document.getElementById('lbImgContainer');
      const img = document.getElementById('lbImg');
      const btn = document.getElementById('lbZoomBtn');
      wrap.classList.toggle('zoomed', state.zoomed);
      btn.classList.toggle('active', state.zoomed);

      if (state.zoomed) {
        if (e && e.clientX) updateZoomOrigin(e);
        img.style.transform = 'scale(1.85)';
        document.getElementById('lbFooterCaption').textContent = 'Move cursor to pan · Click image to reset zoom';
      } else {
        img.style.transform = 'scale(1)';
        img.style.transformOrigin = 'center center';
        document.getElementById('lbFooterCaption').textContent = 'Click image to toggle optical loupe zoom';
      }
    }

    function resetZoom() {
      state.zoomed = false;
      const wrap = document.getElementById('lbImgContainer');
      const img = document.getElementById('lbImg');
      const btn = document.getElementById('lbZoomBtn');
      wrap.classList.remove('zoomed');
      btn.classList.remove('active');
      img.style.transform = 'scale(1)';
      img.style.transformOrigin = 'center center';
    }

    function updateZoomOrigin(e) {
      if (!state.zoomed) return;
      const img = document.getElementById('lbImg');
      const rect = img.getBoundingClientRect();
      const x = Math.max(0, Math.min(100, ((e.clientX - rect.left) / rect.width) * 100));
      const y = Math.max(0, Math.min(100, ((e.clientY - rect.top) / rect.height) * 100));
      img.style.transformOrigin = `${x}% ${y}%`;
    }

    function initLightbox() {
      document.getElementById('lbCloseBtn').addEventListener('click', closeLightbox);
      document.getElementById('lbPrev').addEventListener('click', () => {
        state.lightboxIdx--;
        updateLightboxContent();
      });
      document.getElementById('lbNext').addEventListener('click', () => {
        state.lightboxIdx++;
        updateLightboxContent();
      });
      document.getElementById('lbInfoBtn').addEventListener('click', () => {
        state.drawerOpen = !state.drawerOpen;
        syncDrawerUI();
      });
      document.getElementById('lbZoomBtn').addEventListener('click', () => toggleZoom());

      const imgWrap = document.getElementById('lbImgContainer');
      imgWrap.addEventListener('click', e => toggleZoom(e));
      imgWrap.addEventListener('mousemove', updateZoomOrigin);

      // Click backdrop to close
      document.getElementById('lbStage').addEventListener('click', e => {
        if (e.target.id === 'lbStage') closeLightbox();
      });

      // Touch swipe navigation on mobile
      let touchStartX = 0;
      const stage = document.getElementById('lbStage');
      stage.addEventListener('touchstart', e => {
        touchStartX = e.changedTouches[0].screenX;
      }, { passive: true });
      stage.addEventListener('touchend', e => {
        if (state.zoomed) return;
        const dx = e.changedTouches[0].screenX - touchStartX;
        if (Math.abs(dx) > 55) {
          state.lightboxIdx += dx < 0 ? 1 : -1;
          updateLightboxContent();
        }
      }, { passive: true });

      // Inquire About Print CTA inside Lightbox
      document.getElementById('lbInquirePrintBtn').addEventListener('click', () => {
        const list = state.filteredPlates.length ? state.filteredPlates : PLATES;
        const plate = list[state.lightboxIdx];
        closeLightbox();
        attachPrintToInquiry(plate);
        document.getElementById('inquire').scrollIntoView({ behavior: 'smooth' });
      });

      // Keyboard controls
      document.addEventListener('keydown', e => {
        if (!state.lightboxOpen) return;
        if (e.key === 'Escape') closeLightbox();
        else if (e.key === 'ArrowRight') { state.lightboxIdx++; updateLightboxContent(); }
        else if (e.key === 'ArrowLeft') { state.lightboxIdx--; updateLightboxContent(); }
        else if (e.key.toLowerCase() === 'i') { state.drawerOpen = !state.drawerOpen; syncDrawerUI(); }
        else if (e.key.toLowerCase() === 'z') toggleZoom();
      });
    }

    /* --------------------------------------------------------------------------
       INQUIRY FORM, PRINT ATTACHMENT & STUDIO UTILITIES
       -------------------------------------------------------------------------- */
    function attachPrintToInquiry(plate) {
      const banner = document.getElementById('selectedPrintBanner');
      const nameEl = document.getElementById('selectedPrintName');
      nameEl.textContent = `${plate.title} (${plate.location}, ${plate.year}) — ${plate.edition}`;
      banner.classList.add('visible');

      // Activate Print Acquisition chip
      document.querySelectorAll('#inquiryTypes .type-chip').forEach(c => {
        const isPrint = c.dataset.type === 'Fine Art Print Acquisition';
        c.classList.toggle('active', isPrint);
      });
      document.getElementById('inquiryTypeInput').value = 'Fine Art Print Acquisition';

      const details = document.getElementById('projectDetails');
      if (!details.value.trim()) {
        details.value = `Hello Clara,\n\nI would like to inquire about acquiring a signed archival print of "${plate.title}" (${plate.edition}). Please share framing and shipping details.`;
      }
      showToast(`Attached "${plate.title}" to your inquiry`);
    }

    function initInquiry() {
      const chips = document.querySelectorAll('#inquiryTypes .type-chip');
      const hiddenType = document.getElementById('inquiryTypeInput');

      chips.forEach(chip => {
        chip.addEventListener('click', () => {
          chips.forEach(c => c.classList.remove('active'));
          chip.classList.add('active');
          hiddenType.value = chip.dataset.type;
        });
      });

      document.getElementById('clearPrintBtn').addEventListener('click', () => {
        document.getElementById('selectedPrintBanner').classList.remove('visible');
      });

      // Copy studio email
      document.getElementById('copyEmailBtn').addEventListener('click', async () => {
        const email = 'studio@claramoreau.photo';
        try {
          await navigator.clipboard.writeText(email);
          showToast('Copied studio@claramoreau.photo');
        } catch {
          showToast('Email: studio@claramoreau.photo');
        }
      });

      // Form submission
      const form = document.getElementById('inquiryForm');
      const successBox = document.getElementById('formSuccess');

      form.addEventListener('submit', e => {
        e.preventDefault();
        const name = document.getElementById('clientName').value.trim();
        const email = document.getElementById('clientEmail').value.trim();
        const details = document.getElementById('projectDetails').value.trim();

        if (!name || !email || !email.includes('@') || !details) {
          showToast('Please complete your name, valid email, and project notes.');
          return;
        }

        const type = hiddenType.value;
        document.getElementById('formSuccessMsg').textContent =
          `Thank you, ${name}. Your ${type.toLowerCase()} note has been received by the studio desk — I will reply to ${email} within 48 hours.`;
        form.style.display = 'none';
        successBox.classList.add('visible');
        showToast('Inquiry sent to Clara Moreau Studio');
      });

      document.getElementById('resetFormBtn').addEventListener('click', () => {
        form.reset();
        document.getElementById('selectedPrintBanner').classList.remove('visible');
        successBox.classList.remove('visible');
        form.style.display = 'block';
      });
    }

    // Header Scroll & Mobile Menu
    function initNavigation() {
      const header = document.getElementById('siteHeader');
      const onScroll = () => {
        header.classList.toggle('scrolled', window.scrollY > 24);
      };
      window.addEventListener('scroll', onScroll, { passive: true });
      onScroll();

      const btn = document.getElementById('mobileMenuBtn');
      const drawer = document.getElementById('mobileDrawer');
      const toggleDrawer = (force) => {
        const open = typeof force === 'boolean' ? force : !drawer.classList.contains('open');
        drawer.classList.toggle('open', open);
        drawer.setAttribute('aria-hidden', String(!open));
        btn.setAttribute('aria-expanded', String(open));
        document.body.style.overflow = open ? 'hidden' : '';
      };

      btn.addEventListener('click', () => toggleDrawer());
      drawer.querySelectorAll('a').forEach(a => a.addEventListener('click', () => toggleDrawer(false)));
    }

    // Live Paris & Lisbon Studio Clock
    function initClock() {
      document.getElementById('yearNow').textContent = new Date().getFullYear();
      const clockEl = document.getElementById('studioClock');

      const tick = () => {
        try {
          const now = new Date();
          const paris = new Intl.DateTimeFormat('en-GB', {
            timeZone: 'Europe/Paris', hour: '2-digit', minute: '2-digit', hour12: false
          }).format(now);
          const lisbon = new Intl.DateTimeFormat('en-GB', {
            timeZone: 'Europe/Lisbon', hour: '2-digit', minute: '2-digit', hour12: false
          }).format(now);
          clockEl.textContent = `PARIS ${paris} · LISBON ${lisbon}`;
        } catch {
          clockEl.textContent = 'PARIS · LISBON';
        }
      };
      tick();
      setInterval(tick, 30000);
    }

    /* --------------------------------------------------------------------------
       BOOT
       -------------------------------------------------------------------------- */
    document.addEventListener('DOMContentLoaded', () => {
      buildArchive();
      document.getElementById('studioPortraitImg').src = renderStudioPortrait();

      initTheme();
      initNavigation();
      initHero();
      initGalleryControls();
      renderGallery();
      initLightbox();
      initInquiry();
      initClock();
    });
  </script>
</body>
</html>
